#include "../Source/PluginEditor.h"
#include <iostream>
#include <set>
#include <stdexcept>
namespace {void need(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}void set(SpaceInfinityProcessor& p,const juce::String& id,float value){auto* a=p.state.getParameter(id);need(a!=nullptr,"parameter exists");a->setValueNotifyingHost(a->convertTo0to1(value));}
juce::Component* named(juce::Component& c,const juce::String& name){if(c.getName()==name)return &c;for(auto* child:c.getChildren())if(auto* found=named(*child,name))return found;return nullptr;}}
int runOscillatorWorkflowSmoke(){try {
    infinity::UnisonSettings u;u.amount=.8f;for(int mode=0;mode<5;++mode){u.mode=mode;need(u.ratio(0,1,0)==1,"single voice ignores detune");for(int count=2;count<=16;++count)for(int i=0;i<count;++i)need(std::isfinite(u.ratio(i,count,0))&&u.ratio(i,count,0)>.8,"all unison distributions bounded");}u.mode=0;for(int i=1;i<7;++i)need(std::abs((u.ratio(i,7,0)-u.ratio(i-1,7,0))-(u.ratio(1,7,0)-u.ratio(0,7,0)))<1e-10,"linear frequency spacing");for(int count=1;count<=16;++count){u.blend=.75f;for(int i=0;i<count;++i)need(u.weight(i,count)==1,"75 percent blend equal voice levels");u.blend=.05f;if(count<=2)for(int i=0;i<count;++i)need(u.weight(i,count)==1,"blend ignored below three voices");}u.blend=0;need(u.weight(3,7)==1&&u.weight(2,6)==1&&u.weight(3,6)==1&&u.weight(0,7)==0,"odd/even central voices");u.stack=6;need(u.groups()==7&&u.semitones(1,false)==7&&u.semitones(6,false)==36,"fifth/octave stack groups");u.stack=8;need(u.semitones(0,true)==-24&&u.semitones(0,false)==0,"centre sub octave stack");
    const auto waves=SpaceInfinityProcessor::oscillatorWaves();need(waves.size()==37&&waves[30]=="Custom Wavetable"&&waves[31]=="303 Saw","wave indices preserved and acid appended");for(int wave=31;wave<37;++wave){double energy=0,difference=0,mean=0;for(int i=0;i<512;++i){const float a=SpaceInfinityProcessor::oscillatorFrameSample(double(i)/512,wave,0),b=SpaceInfinityProcessor::oscillatorFrameSample(double(i)/512,wave,1);need(std::isfinite(a)&&std::abs(a)<=1.001f&&std::isfinite(b)&&std::abs(b)<=1.001f,"acid frame bounds");energy+=a*a;mean+=a;difference+=(a-b)*(a-b);}std::cout<<"Acid "<<wave<<" energy "<<energy<<" morph delta "<<difference<<" DC sum "<<mean<<"\n";need(energy>10&&difference>1&&std::abs(mean)<.001,"acid families sound, morph and have no DC");}double morph=0;for(int i=0;i<512;++i){const auto a=SpaceInfinityProcessor::oscillatorFrameSample(double(i)/512,0,0),b=SpaceInfinityProcessor::oscillatorFrameSample(double(i)/512,0,1);morph+=(a-b)*(a-b);}need(morph>10,"built-in frame position changes actual waveform");
    auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);std::set<int> indices;for(int source=0;source<9;++source)for(int slot=0;slot<16;++slot){indices.insert(p->flexibleRouteIndex(source,slot));need(p->state.getParameter(p->flexibleDepthId(source,slot))!=nullptr,"every source has sixteen amounts");}need(indices.size()==144&&*indices.begin()==0&&*indices.rbegin()==143,"all old/new route slots distinct");
    const char* targets[]{"delayWetLowFreq","delayWetLowGain","delayWetLowQ","delayWetMidFreq","delayWetMidGain","delayWetMidQ","delayWetHighFreq","delayWetHighGain","delayWetHighQ","reverbWetLowFreq","reverbWetLowGain","reverbWetLowQ","reverbWetMidFreq","reverbWetMidGain","reverbWetMidQ","reverbWetHighGain"};for(int source=0;source<9;++source)for(int slot=0;slot<16;++slot){const int target=p->flexibleTargetIndex(targets[slot]);need(target>=0,"FX target available");p->assignFlexibleSource(source,slot,target);need(p->flexibleSourceTarget(source,slot)==target,"all macro/LFO destinations assigned");}for(int source=0;source<3;++source){need(p->dropModulation("INFINITY:PERFORMANCE:"+juce::String(source),"delayWetMidGain"),"performance macro can drag to FX");need(!p->modulationDepthFor("INFINITY:PERFORMANCE:"+juce::String(source),"delayWetMidGain").isEmpty(),"performance macro target-side amount");}need(p->flexibleTargetIndex("sampleStart")>=0&&p->flexibleTargetIndex("sampleRoot")>=0,"sample controls are live destinations");
    set(*p,"osc2WTPos",.68f);set(*p,"osc1UnisonMode",3);set(*p,"osc1Stack",5);set(*p,"osc1Range",72);juce::MemoryBlock saved;p->getStateInformation(saved);auto recalled=std::make_unique<SpaceInfinityProcessor>();recalled->setStateInformation(saved.getData(),int(saved.getSize()));for(int source=0;source<9;++source)for(int slot=0;slot<16;++slot)need(recalled->flexibleSourceTarget(source,slot)==p->flexibleSourceTarget(source,slot),"all sixteen routes recall");need(std::abs(recalled->state.getRawParameterValue("osc2WTPos")->load()-.68f)<.00001,"independent oscillator position recall");
    auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());editor->setSize(800,760);for(int i=1;i<=2;++i){auto* knob=named(*editor,"Oscillator "+juce::String(i)+" wavetable position");need(knob&&knob->isVisible(),"both WT POS knobs visible");need(named(*editor,"Oscillator "+juce::String(i)+" unison options")!=nullptr,"unison options accessible");}
    auto* gain=dynamic_cast<ModSlider*>(named(*editor,"Oscillator 1 gain"));need(gain!=nullptr,"gain drag target");p->assignFlexibleSource(0,0,p->flexibleTargetIndex("osc1Gain"));const auto depth=p->flexibleDepthId(0,0);set(*p,depth,.2f);const float base=p->state.getRawParameterValue("osc1Gain")->load();auto bounds=gain->getLocalBounds().toFloat();bounds.removeFromBottom(float(gain->getTextBoxHeight()));const float radius=juce::jmin(43.0f,juce::jmin(bounds.getWidth(),bounds.getHeight())*.44f)*1.13f;const auto at=bounds.getCentre()+juce::Point<float>(radius,0);const auto mouse=[&](juce::Point<float> pos,bool drag){return juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),pos,juce::ModifierKeys(juce::ModifierKeys::leftButtonModifier),1,0,0,0,0,gain,gain,juce::Time::getCurrentTime(),at,juce::Time::getCurrentTime(),1,drag);};gain->mouseDown(mouse(at,false));gain->mouseDrag(mouse(at.translated(0,-20),true));gain->mouseUp(mouse(at.translated(0,-20),true));need(p->state.getRawParameterValue(depth)->load()>.3f&&p->state.getRawParameterValue("osc1Gain")->load()==base,"drag modulation ring edits amount without changing base value");editor.reset();
    auto legacyPosition=std::make_unique<SpaceInfinityProcessor>();set(*legacyPosition,"independentWTPos",0);need(legacyPosition->dropModulation("INFINITY:LFO:0","osc2WTPos"),"B position assignment from old preset");need(legacyPosition->state.getRawParameterValue("independentWTPos")->load()==1,"assigning B WT POS activates independent positioning");
    p->loadPreset(0);for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","osc2Enabled"})set(*p,id,0);set(*p,"osc1Unison",16);set(*p,"subLevel",0);set(*p,"gain",.2f);p->prepareToPlay(48000,64);juce::AudioBuffer<float> b(2,64);for(int mode=0;mode<5;++mode)for(int stack=0;stack<9;++stack){set(*p,"osc1UnisonMode",float(mode));set(*p,"osc1Stack",float(stack));set(*p,"wave",float(31+mode%6));set(*p,"wavetableScan",float(mode)/4);juce::MidiBuffer midi;if(mode==0&&stack==0)midi.addEvent(juce::MidiMessage::noteOn(1,48,.5f),0);p->processBlock(b,midi);for(int ch=0;ch<2;++ch)for(int i=0;i<64;++i)need(std::isfinite(b.getSample(ch,i)),"maximum stack modes produce finite audio");}
    std::cout<<"Oscillators/macros: five unison modes, blend centres, stacks, six acid families, frame morphing, sixteen destinations per source, UI, recall and maximum stack stability passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Oscillator workflow failure: "<<e.what()<<'\n';return 123;}}
